package com.prismpdf.editor.graphics

import android.graphics.Bitmap
import android.graphics.Color
import android.graphics.PointF

class SubPixelSnappingEngine {

    /**
     * Scans a localized search radius inside the binary OpenCV edge tracking mask to find the
     * closest microprint guideline pixel, computing sub-pixel coordinate alignment corrections.
     *
     * @param targetTouchPdfCoordinates The raw mapped touch target point calculated in PDF point space.
     * @param edgeMaskBitmap The binary high-DPI vector edge mask layer generated by OpenCV.
     * @param mapper The active system PDFCoordinateMapper layout instance.
     * @param scanRadiusPixels The search window constraint in physical screen pixels (default 12px).
     * @return A PointF containing corrected PDF coordinates, snapped cleanly onto the background baseline.
     */
    fun computeSnappedPdfCoordinates(
        targetTouchPdfCoordinates: PointF,
        edgeMaskBitmap: Bitmap,
        mapper: PDFCoordinateMapper,
        scanRadiusPixels: Int = 12
    ): PointF {
        // Map PDF point inputs to exact current raster matrix pixel locations
        val screenPoint = mapper.pdfToScreen(targetTouchPdfCoordinates.x, targetTouchPdfCoordinates.y)
        val startX = screenPoint.x.toInt()
        val startY = screenPoint.y.toInt()

        var closestPoint: PointF? = null
        var minimumDistanceSquared = Double.MAX_VALUE

        // Scan the local window region mapping grids
        for (deltaY in -scanRadiusPixels..scanRadiusPixels) {
            for (deltaX in -scanRadiusPixels..scanRadiusPixels) {
                val currentX = startX + deltaX
                val currentY = startY + deltaY

                // Protect array boundaries from out-of-bounds frame access leaks
                if (currentX >= 0 && currentX < edgeMaskBitmap.width && currentY >= 0 && currentY < edgeMaskBitmap.height) {
                    val pixelColor = edgeMaskBitmap.getPixel(currentX, currentY)

                    // In a binary edge mask, white pixels (255) signal a verified structural line vector anchor
                    if (Color.red(pixelColor) > 200) {
                        val distanceSquared = (deltaX * deltaX + deltaY * deltaY).toDouble()
                        if (distanceSquared < minimumDistanceSquared) {
                            minimumDistanceSquared = distanceSquared
                            closestPoint = PointF(currentX.toFloat(), currentY.toFloat())
                        }
                    }
                }
            }
        }

        // Return original coordinates if no structural guide vector is present within the bounding window
        if (closestPoint == null) return targetTouchPdfCoordinates

        // Inverse map the optimal screen tracking pixel back into physical PDF point coordinates
        return mapper.screenToPdf(closestPoint.x, closestPoint.y)
    }
}
